import{z as s,x as l,o as A,c as i,q as B,j as t,D as a,d as n,s as r,S as o}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"高频统计深化收束","description":"","frontmatter":{"title":"高频统计深化收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hfs-map.md","filePath":"quant/hfs-map.md","lastUpdated":1791063341000}'),d={name:"quant/hfs-map.md"};function p(D,E,h,F,m,_){const e=l("Mermaid");return A(),i("div",null,[E[2]||(E[2]=B('<h1 id="高频统计深化收束" tabindex="-1">高频统计深化收束 <a class="header-anchor" href="#高频统计深化收束" aria-label="Permalink to &quot;高频统计深化收束&quot;">​</a></h1><div class="epigraph"><p>估计量会更新，次序不会：对象、诊断、估计量、检验、对齐、频率——六个决定按序签字，然后才轮到预报与组合。</p><footer>—— 据本课程各课与 Andersen, Bollerslev and Diebold, Econometrica 2003 的口径整理</footer></div><p><a href="/quant/hfs-frequency-choice">上一课</a>把频率写成决策程序，八课的零件到齐。本课是本课程的收束：把族谱、噪声修正、跳、beta、噪声实证、多元相关、频率选择收成一张按序签字的检查单，把高频失败模式归成几类，并把产出接回主干——HAR 预报与已实现 GARCH 吃这里的日度序列，风险与执行吃这里的协方差矩阵与频率表。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>这套统计的失败很少死于单个估计量，几乎都死于次序：没声明对象就选估计量，没测噪声就定带宽，没降噪就检验跳，没对齐就算相关，没跑程序就迁移频率。每一步单看都有人写过；缺口是把依赖关系钉死成流程——后面的决定吃什么输入，错了又污染谁。</p><p><span class="marginnote">直觉类比：这张检查单像做菜的备料次序——火候再好，把盐当成糖放了（对象口径错），这道菜也救不回来。先确认每样料是什么，再谈怎么烹；顺序反了，手艺越好浪费越多。</span></p><h3 id="六个决定-按序签字" tabindex="-1">六个决定，按序签字 <a class="header-anchor" href="#六个决定-按序签字" aria-label="Permalink to &quot;六个决定，按序签字&quot;">​</a></h3><p><strong>一、对象</strong>：估总二次变差还是连续 \\(IV\\)，还是协变差；含不含隔夜、中点还是成交价、日方差还是年化——口径写死（第一课）。<strong>二、诊断</strong>：签名图与噪声-信号比，跳的初查（第一、五课）。<strong>三、估计量</strong>：按诊断选支，调参带准则（第二课）。<strong>四、跳</strong>：降噪后检验、定位、分账（第三课）。<strong>五、对齐</strong>：多元先定对齐方案，半正定靠构造（第四、六课）。<strong>六、频率</strong>：按目标与噪声-信号比出频率表（第七课）。顺序反了的典型事故：先定五分钟再挑对象，带宽与口径互相将就，最后报告里连「估的是什么」都说不清。</p><p><span class="marginnote">检查单上最便宜的一行是第一行：对象口径一次写错，后面五个决定做得再好，产出也接不进下游——HAR 吃不到对的日度序列，优化器吃不到对的矩阵。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2>',10)),(A(),t(o,null,{default:a(()=>[r(e,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20O%5B%22%E4%B8%80%E3%80%81%E5%AF%B9%E8%B1%A1%E5%8F%A3%E5%BE%84%22%5D%20--%3E%20G%5B%22%E4%BA%8C%E3%80%81%E8%AF%8A%E6%96%AD%EF%BC%9A%E7%AD%BE%E5%90%8D%E5%9B%BE%20%2B%20%E5%99%AA%E5%A3%B0-%E4%BF%A1%E5%8F%B7%E6%AF%94%20%2B%20%E8%B7%B3%E5%88%9D%E6%9F%A5%22%5D%0A%20%20G%20--%3E%20E%5B%22%E4%B8%89%E3%80%81%E4%BC%B0%E8%AE%A1%E9%87%8F%E4%B8%8E%E8%B0%83%E5%8F%82%E5%87%86%E5%88%99%22%5D%0A%20%20E%20--%3E%20J%5B%22%E5%9B%9B%E3%80%81%E8%B7%B3%EF%BC%9A%E6%A3%80%E9%AA%8C%E3%80%81%E5%AE%9A%E4%BD%8D%E3%80%81%E5%88%86%E8%B4%A6%22%5D%0A%20%20J%20--%3E%20L%5B%22%E4%BA%94%E3%80%81%E5%AF%B9%E9%BD%90%E4%B8%8E%E5%8D%8A%E6%AD%A3%E5%AE%9A%E7%9F%A9%E9%98%B5%22%5D%0A%20%20L%20--%3E%20F%5B%22%E5%85%AD%E3%80%81%E9%A2%91%E7%8E%87%E8%A1%A8%E6%8C%89%E7%9B%AE%E6%A0%87%E5%87%BA%22%5D%0A%20%20F%20--%3E%20D1%5B%22%E4%B8%8B%E6%B8%B8%20A%EF%BC%9AHAR%20%E4%B8%8E%E5%B7%B2%E5%AE%9E%E7%8E%B0%20GARCH%20%E7%9A%84%E6%97%A5%E5%BA%A6%E5%BA%8F%E5%88%97%22%5D%0A%20%20F%20--%3E%20D2%5B%22%E4%B8%8B%E6%B8%B8%20B%EF%BC%9A%E5%AF%B9%E5%86%B2%E6%AF%94%E3%80%81%E9%A3%8E%E9%99%A9%E5%88%86%E8%A7%A3%E3%80%81%E7%BB%84%E5%90%88%E7%9F%A9%E9%98%B5%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>次序的机制理由是<strong>条件的方向</strong>：带宽要吃噪声估计，检验要吃降噪路径，beta 要吃对齐方案，频率表要吃全部上游——下游决定无法在上游不定时独立做出。失败模式也按次序归档：<strong>口径漂移</strong>（对象含混，产出接不上）；<strong>诊断跳步</strong>（噪声当波动、季节性当跳）；<strong>次序倒置</strong>（先频率后对象、先检验后降噪）；<strong>维度越权</strong>（\\(N\\gt n\\) 强行满秩）；<strong>结论迁移</strong>（A 标的的频率表搬到 B 标的）。每类事故都在前面某课有一个具体的死法，收束课只做一件事：把死法挂回步骤，让检查单长出记忆。</p>',2)),(A(),t(o,null,{default:a(()=>[r(e,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E8%AF%8A%E6%96%AD%E8%B7%B3%E6%AD%A5%3A%20%E5%99%AA%E5%A3%B0%E8%A2%AB%E5%BD%93%E6%88%90%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20E%5B%22%E4%BC%B0%E8%AE%A1%E9%87%8F%E9%80%89%E9%94%99%E6%94%AF%3A%20%E5%B8%A6%E5%AE%BD%E5%B0%86%E5%B0%B1%22%5D%0A%20%20E%20--%3E%20J%5B%22%E8%B7%B3%E6%A3%80%E9%AA%8C%20size%20%E5%9D%8F%3A%20%E5%AD%A3%E8%8A%82%E6%80%A7%E8%AF%AF%E6%8A%A5%E6%88%90%E8%B7%B3%22%5D%0A%20%20J%20--%3E%20L%5B%22%E5%AF%B9%E9%BD%90%E4%B8%8E%E6%8B%86%E8%B4%A6%E5%A4%B1%E7%9C%9F%3A%20%E7%9B%B8%E5%85%B3%E8%A2%AB%E5%8E%8B%E5%B0%8F%22%5D%0A%20%20L%20--%3E%20FQ%5B%22%E9%A2%91%E7%8E%87%E8%A1%A8%E9%94%99%E9%85%8D%3A%20%E6%A0%BC%E8%B7%9D%E4%B8%8E%E5%AF%B9%E8%B1%A1%E4%BA%92%E7%9B%B8%E5%B0%86%E5%B0%B1%22%5D%0A%20%20FQ%20--%3E%20D%5B%22%E4%B8%8B%E6%B8%B8%E5%85%A8%E7%81%AD%3A%20HAR%20%E5%BA%8F%E5%88%97%E4%B8%8E%E7%BB%84%E5%90%88%E7%9F%A9%E9%98%B5%E4%B8%8D%E5%8F%AF%E7%94%A8%22%5D%0A%20%20FIX%5B%22%E5%9B%9E%E5%88%B0%E7%AC%AC%E4%B8%80%E8%A1%8C%E9%87%8D%E7%AD%BE%3A%20%E5%AF%B9%E8%B1%A1%E4%B8%8E%E8%AF%8A%E6%96%AD%E5%85%88%E8%A1%8C%22%5D%20--%3E%20F%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">为什么重要（一个环节错的传播）：噪声-信号比只需测错一个数量级，带宽就错、\\(IV\\) 偏、跳检验误报、日度序列漂移、HAR 预报失真，最后波动率目标组合的仓位整体偏——溯源到头，源头只是一次诊断跳步。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程的口径止于价格过程的统计读数：队列与订单流的估计、执行侧的冲击测量、把日内信息放进组合优化的正则化选择，分别归订单簿动力学、执行与组合课程。噪声与跳的模型在演进，六个决定的次序不随估计量版本变化——这是收束课敢写检查单的原因。读数之外的解释（消息、行为、市场质量的经济含义）只留接口，不在这里下结论。</p><p><span class="marginnote">常见误区：「出了新估计量，把旧流程整个换掉就行。」实际上估计量会过时，六个决定的次序不会变——升级只动第三格，前两格（对象、诊断）与后三格的接口照旧。把流程和估计量捆死重写，才是最容易引入新事故的做法。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>六个决定按序签字：对象、诊断、估计量、跳、对齐、频率；顺序是条件方向的倒影。</li><li>失败按次序归档：口径漂移、诊断跳步、次序倒置、维度越权、结论迁移。</li><li>产出两条下行动线：日度 \\(IV\\) 序列接 HAR 与已实现 GARCH，矩阵与频率表接对冲、风险与组合。</li><li>检查单第一行最便宜也最致命：对象口径错了，后面全对不了。</li><li>出处：本课程各课；口径基线见 Andersen, Bollerslev and Diebold, <em>Econometrica</em>, 2003；Barndorff-Nielsen and Shephard, 2004 与 2006；Zhang, Mykland and Aït-Sahalia, <em>JASA</em>, 2005；Aït-Sahalia, Mykland and Zhang, <em>RFS</em>, 2005。</li></ul>',6))])}const f=s(d,[["render",p]]);export{c as __pageData,f as default};
